package com.ruoyi.web.controller.shop;
import org.springframework.beans.factory.annotation.Autowired; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import com.ruoyi.common.annotation.Log; import com.ruoyi.common.core.controller.BaseController; import com.ruoyi.common.core.domain.AjaxResult; import com.ruoyi.common.enums.BusinessType; import com.ruoyi.system.domain.shop.MallInventoryAdjust; import com.ruoyi.system.service.IMallInventoryService;
@RestController @RequestMapping("/shop/inventory") public class MallInventoryController extends BaseController { @Autowired private IMallInventoryService service; @PreAuthorize("@ss.hasPermi('shop:product:stock')") @Log(title="商城库存",businessType=BusinessType.UPDATE) @PostMapping("/adjust") public AjaxResult adjust(@RequestBody MallInventoryAdjust adjust){return toAjax(service.adjust(adjust,getUsername()));} }
